#pragma once

#include <cstddef>
#include <cstdint>

namespace b3::b3derivatives::binaryentrypoint::sbe::v8_0 {


// Length of free format text string generated by exchange.
struct TextLength {

    static constexpr auto name = "Text Length";
    static constexpr std::size_t size = 1;
    using type = std::uint8_t;

    // default constructor
    constexpr TextLength()
     : value{ 0 } {}

    // standard constructor
    constexpr explicit TextLength(const std::uint8_t &value)
     : value{ value } {}

    // get value of TextLength field
    [[nodiscard]] std::uint8_t get() const {
        return value;
    }

  protected:
    std::uint8_t value;
};
}
